// Pula receitas que citam item de mod ausente (ex.: mod removido do pack)
function modsDaReceita(json) {
  let mods = []
  JSON.stringify(json).replace(/"(?:item|id)":\s*"([a-z0-9_.-]+):/g, (m, ns) => { mods.push(ns) })
  return mods
}

ServerEvents.recipes(event => {
  RECEITAS_POKEMON_REMOVER.forEach(item => event.remove({ output: item }))
  let puladas = 0
  RECEITAS_POKEMON.forEach(r => {
    if (modsDaReceita(r.json).some(ns => ns != 'minecraft' && !Platform.isLoaded(ns))) { puladas++; return }
    event.custom(r.json).id(r.id)
  })
  if (puladas > 0) console.info(`receitas_pokemon: ${puladas} receitas puladas (mod ausente)`)
})
